// Convert the checked-in SVG logos into compact, color-independent LVGL alpha masks.
const fs = require('node:fs');
const path = require('node:path');
const sharp = require(process.env.PANEL_SHARP || 'sharp');
const firmware = path.resolve(__dirname, '..');
const source = path.join(firmware, 'assets/provider-logos');
const size = 20;

(async () => {
  const lines = [
    '// Generated by firmware/tools/generate-provider-logos.cjs; do not edit mask bytes.',
    '// Source revision and license: firmware/assets/provider-logos/.',
    '#pragma once', '#include "lvgl.h"', '',
  ];
  for (const brand of ['claude', 'chatgpt', 'deepseek']) {
    const svg = fs.readFileSync(path.join(source, brand + '.svg'));
    const mask = await sharp(svg, {density: 288}).resize(size, size).ensureAlpha().extractChannel(3).raw().toBuffer();
    if (mask.length !== size * size || !mask.some(v => v > 0)) throw Error('Invalid mask: '+brand);
    lines.push(`static constexpr uint8_t panel_logo_${brand}[] = {`);
    for (let start = 0; start < mask.length; start += 20) {
      lines.push('    '+[...mask.subarray(start, start + 20)].map(n => '0x'+n.toString(16).padStart(2,'0')).join(',')+',');
    }
    lines.push('};','');
  }
  lines.push(
    'static constexpr lv_img_dsc_t panel_logo_descriptor(const uint8_t *alpha) {',
    '    lv_img_dsc_t image = {};',
    '    image.header.cf = LV_IMG_CF_ALPHA_8BIT;',
    `    image.header.w = ${size}; image.header.h = ${size};`,
    `    image.data_size = ${size * size}; image.data = alpha;`,
    '    return image;', '}', '',
    'static constexpr lv_img_dsc_t panel_provider_logos[] = {',
    '    panel_logo_descriptor(panel_logo_claude),',
    '    panel_logo_descriptor(panel_logo_chatgpt),',
    '    panel_logo_descriptor(panel_logo_deepseek),',
    '};',''
  );
  fs.writeFileSync(path.join(firmware,'ai-status-screen/provider_logos.h'),lines.join('\n'));
  console.log('Generated three 20x20 LVGL alpha masks: 1200 bytes of pixel data total.');
})().catch(error => { console.error(error); process.exitCode=1; });
